Definition annotate_entry := 0xbc724%Z.

Section ANNOTATE.
  Context {HCEIL : HeapCeil}.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : word -> option byte) (beg len oldmid newmid lo : Z).
  Hypothesis ALG : beg mod 8 = 0 /\ len mod 8 = 0 /\ oldmid mod 8 = 0 /\ newmid mod 8 = 0.
  Hypothesis LEN : 0 <= len <= 2^16.
  Hypothesis MIDS : beg <= oldmid <= beg + len /\ beg <= newmid <= beg + len.
  Hypothesis RNG : app_rng beg (beg + len).
  Hypothesis SH0 : SHAD m beg (cc_shadow len (oldmid - beg)).
  Hypothesis ST0 : stk asegs m lo (bv_unsigned sp).
  Hypothesis CEIL : aceil <= lo.
  Hypothesis LO : lo <= bv_unsigned sp - AINTRIN_STACK.
  Hypothesis MI : mem_inv asegs m.
  Hypothesis AC : ACONST m.

  Hypothesis THR : rw_cells asegs m ACF_CLRTHR_CELL [C8 (Z_to_bv 64 18446744073709551615)].
  Hypothesis DCO : rw_cells asegs m ADCO_CELL [C1 (Z_to_bv 8 1)].
  Hypothesis GVB : rw_cells asegs m AGOT_VERB [C8 (Z_to_bv 64 AVERB_CELL)].
  Hypothesis VB : rw_cells asegs m AVERB_CELL [C4 (Z_to_bv 64 0)].

  Notation POST := (annotate_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc beg len newmid lo m).
  Notation SP2 := (Z_to_bv 64 (bv_unsigned sp + -2128)).
  Notation W := [(sh beg, sh beg + len / 8); (bv_unsigned sp - 4096, bv_unsigned sp)].
  Notation FRAME mm := (rw_cells asegs mm (bv_unsigned sp + -56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).

  Section JE.
    Variables (mm : word -> option byte) (fjunk : list byte).
    Hypothesis MIm : mem_inv asegs mm.
    Hypothesis FR1 : FRAME mm.
    Hypothesis FR : rw_cells asegs mm (bv_unsigned sp + -2128) [CB 2072 fjunk].
    Hypothesis STm : stk asegs mm lo (bv_unsigned sp + -2128).
    Hypothesis MU : munch W m mm.
    Hypothesis WM : wmono asegs m mm.
    Hypothesis SHm : SHAD mm beg (cc_shadow len (newmid - beg)).

    Lemma ann_je : forall (x1 x5 x6 x7 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x28 x29 x30 x31 : word),
      evt asegs POST (MS (mkR x1 SP2 gp tp x5 x6 x7 sp x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
                         F (Z_to_bv 64 0xbc98c) fc None mm (seg_rom asegs)).
